/**
 * FileStation - 프론트엔드 애플리케이션
 */

// === Blob URL 추적 모듈 ===
// hls.js 등 라이브러리가 만든 MediaSource blob URL이 정리 누락되어 소리가 계속 나는 문제 해결용
// 비디오 재생 중에 만들어지는 MediaSource blob만 추적 (다운로드/vault 등 일반 Blob은 추적 안 함)
(function() {
    const TRACKED_BLOBS = new Set();
    let trackingEnabled = false;  // 비디오 재생 중일 때만 추적
    const origCreate = URL.createObjectURL.bind(URL);
    const origRevoke = URL.revokeObjectURL.bind(URL);
    
    URL.createObjectURL = function(obj) {
        const url = origCreate(obj);
        // ★ MediaSource만 추적 — 일반 Blob(다운로드 링크, vault 프리뷰 등)은 제외
        // 이렇게 안 하면 영상 재생 중 다른 파일 다운로드 blob까지 추적되어, 모달 닫을 때 같이 revoke됨 = 다운로드 링크 깨짐
        if (trackingEnabled && obj && typeof MediaSource !== 'undefined' && obj instanceof MediaSource) {
            TRACKED_BLOBS.add(url);
        }
        return url;
    };
    
    URL.revokeObjectURL = function(url) {
        TRACKED_BLOBS.delete(url);
        return origRevoke(url);
    };
    
    // 비디오 재생 시작할 때 호출 — 이 시점부터 만들어지는 MediaSource blob 추적 시작
    window._startBlobTracking = function() {
        trackingEnabled = true;
    };
    
    // 모달 정리 시 호출 — 추적된 모든 MediaSource blob URL revoke 후 추적 중지
    window._revokeAllTrackedBlobs = function() {
        const count = TRACKED_BLOBS.size;
        TRACKED_BLOBS.forEach(url => {
            try { origRevoke(url); } catch(e) {}
        });
        TRACKED_BLOBS.clear();
        trackingEnabled = false;
        return count;
    };
    
    // 현재 추적 중인 blob 확인용 (디버그)
    window._getTrackedBlobs = function() {
        return Array.from(TRACKED_BLOBS);
    };
})();

// === 클라이언트 상태 추적 모듈 (디버깅용) ===
// 서버측 data/session_debug.log가 활성화됐을 때 프론트 pending 요청 상태를 서버에 보고
// 평상시에는 네트워크 요청 몇 번만 추가되고 오버헤드 거의 없음
(function() {
    const STATE = {
        pending: new Map(),  // fetchId → {url, startTs}
        nextId: 0,
        reportedStuck: new Set(),  // 이미 STUCK 보고한 fetchId (중복 방지)
    };
    
    // 원본 fetch 저장 후 가로채기
    const origFetch = window.fetch.bind(window);
    window.fetch = function(input, init) {
        const url = typeof input === 'string' ? input : (input && input.url) || '?';
        // client_state 자기 자신은 추적 제외 (무한 루프 방지)
        if (url.indexOf('action=client_state') !== -1) {
            return origFetch(input, init);
        }
        const id = ++STATE.nextId;
        const startTs = performance.now();
        STATE.pending.set(id, { url: url, startTs: startTs });
        
        return origFetch(input, init).finally(() => {
            STATE.pending.delete(id);
            STATE.reportedStuck.delete(id);
        });
    };
    
    // 현재 pending 요청 스냅샷 (나이 포함)
    function snapshot() {
        const now = performance.now();
        const arr = [];
        STATE.pending.forEach((info, id) => {
            // URL 축약 (쿼리스트링 길이 제한)
            let url = info.url;
            if (url.length > 200) url = url.substring(0, 200) + '...';
            arr.push({
                id: id,
                url: url,
                age_ms: Math.round(now - info.startTs)
            });
        });
        // 나이 많은 순으로 정렬
        arr.sort((a, b) => b.age_ms - a.age_ms);
        return arr;
    }
    
    // 서버에 상태 보고 (fire-and-forget)
    function report(reason) {
        const pending = snapshot();
        const body = {
            reason: reason,
            pending: pending,
            visibility: document.visibilityState || 'unknown',
            online: navigator.onLine !== false,
            url: location.pathname + location.hash
        };
        try {
            // keepalive로 페이지 종료 시에도 전송 시도
            origFetch('api.php?action=client_state', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(body),
                keepalive: true
            }).catch(() => {});
        } catch(e) {}
    }
    
    // 주기적 heartbeat (10초마다, 단 pending 1개 이상일 때만)
    setInterval(() => {
        if (STATE.pending.size > 0) {
            report('heartbeat');
        }
    }, 10000);
    
    // 긴 pending 감지 (3초마다 체크, 5초 이상 걸린 요청 발견 시 STUCK 신호)
    setInterval(() => {
        const now = performance.now();
        let stuckFound = false;
        STATE.pending.forEach((info, id) => {
            const age = now - info.startTs;
            // 5초 이상 걸리면 한 번만 STUCK 보고 (같은 요청 중복 보고 방지)
            if (age > 5000 && !STATE.reportedStuck.has(id)) {
                STATE.reportedStuck.add(id);
                stuckFound = true;
            }
        });
        if (stuckFound) {
            report('stuck_request');
        }
        // 무한로딩 임계치: pending 5개 이상이 각자 10초 초과
        let manyOld = 0;
        STATE.pending.forEach((info) => {
            if (now - info.startTs > 10000) manyOld++;
        });
        if (manyOld >= 5) {
            report('stuck_many');
        }
    }, 3000);
    
    // 페이지 가시성 변경 시 보고 (탭 전환/복귀)
    document.addEventListener('visibilitychange', () => {
        if (STATE.pending.size > 0) {
            report('visibility_' + document.visibilityState);
        }
    });
    
    // 디버깅용 콘솔 접근
    window._fsPendingSnapshot = snapshot;
    window._fsReportNow = () => report('manual');
})();

// === [HLS_DIAG] 멀티오디오 회귀 진단 모듈 (펜닐님 진단용 — 임시) ===
// 다음 디버깅 위해 보존. 진단 끝나면 window._hlsDiag = false로 비활성.
//
// 사용법:
//   1. F12 콘솔에서: window._hlsDiag = true (진단 시작)
//   2. 음악 폴더 공유 재생 → 동영상 폴더 재생 → 멀티오디오 영상 → 증상 재현
//   3. 서버 GET 요청: /api.php?action=hls_diag_log → 로그 텍스트 다운로드
//   4. 비울 때: /api.php?action=hls_diag_log&clear=1
//
// 클라이언트 호출:
//   App._diagLog('event_name', { key: value })  → 서버 data/hls_diag.log에 시간순 누적
//
// 기록 대상:
//   - 동영상 폴더 진입 / 트랜스코딩 시작 / segment fetch / append / bufferStalledError
//   - 음악 공유 폴더 진입 / 트랙 재생 / cover 요청 / lyrics 요청
//   - HLS 인스턴스 생성 / destroy / 모달 cleanup
//   - 멀티오디오 info API 응답 / audio_tracks 검출
(function() {
    // 진단 토글 (기본 false — 명시적으로 켜야 활성)
    if (typeof window._hlsDiag === 'undefined') window._hlsDiag = false;
    
    let logQueue = [];
    let flushTimer = null;
    
    // 큐에 쌓인 로그를 서버에 일괄 전송 (네트워크 오버헤드 최소화)
    function flushQueue() {
        if (logQueue.length === 0) return;
        const items = logQueue.slice();
        logQueue.length = 0;
        items.forEach(item => {
            try {
                const fd = new FormData();
                fd.append('event', item.event);
                fd.append('data', item.data);
                fetch('api.php?action=hls_diag_log', {
                    method: 'POST',
                    body: fd,
                    credentials: 'same-origin',
                    keepalive: true  // 페이지 종료 시에도 전송 시도
                }).catch(() => {});
            } catch(e) {}
        });
    }
    
    // 외부 노출 — 로그 호출 (window.App._diagLog 또는 window._diagLog)
    window._diagLog = function(event, data) {
        if (!window._hlsDiag) return;
        try {
            const dataStr = (typeof data === 'object' && data !== null)
                ? JSON.stringify(data)
                : String(data || '');
            // 클라이언트 시간 추가 (밀리초 단위 — 서버 시간보다 정밀)
            const ts = (performance.now() / 1000).toFixed(3);
            logQueue.push({ event: '[' + ts + 's] ' + event, data: dataStr });
            // 100ms 디바운싱 — 빠른 연속 호출 모아서 전송
            if (flushTimer) clearTimeout(flushTimer);
            flushTimer = setTimeout(() => { flushTimer = null; flushQueue(); }, 100);
        } catch(e) {}
    };
})();

// === [COVER_DIAG] iOS 음악 썸네일 누락 진단 모듈 (펜닐님 진단용 — 임시) ===
