        // 전송 취소 버튼 (단일 전송용 - 멀티 세션은 각 UI에서 별도 처리)
        document.getElementById('transfer-cancel')?.addEventListener('click', () => {
            // 멀티 다운로드/업로드 세션이 있으면 여기서 처리하지 않음 (각 showMulti*UI에서 onclick으로 처리)
            if (this.multiDownload.sessions.size > 0 || this.multiUpload.sessions.size > 0 || this.multiTransfer.sessions.size > 0) {
                return;
            }
            const type = this.transfer.type || 'upload';
            this.transfer.cancelled = true;
            // 진행 중인 요청 중단
            if (this.transfer.abortController) {
                this.transfer.abortController.abort();
            }
            this.hideTransferProgress();
            const msgs = {
                'upload': [t('upload_cancelled', '업로드가 취소되었습니다'), t('cancel_upload', '업로드 취소')],
                'download': [t('download_cancelled', '다운로드가 취소되었습니다'), t('cancel_download', '다운로드 취소')],
                'copy': [t('copy_cancelled', '복사가 취소되었습니다'), t('cancel_copy', '복사 취소')],
                'move': [t('move_cancelled', '이동이 취소되었습니다'), t('cancel_move', '이동 취소')],
                'delete': [t('delete_cancelled', '삭제가 취소되었습니다'), t('cancel_delete', '삭제 취소')]
            };
            const msg = msgs[type] || msgs['upload'];
            this.toastResponsive(msg[0], msg[1], 'info');
        });
        
