        // 브라우저 기본 우클릭 메뉴 차단 (전체 페이지)
        document.addEventListener('contextmenu', (e) => {
            // input, textarea에서는 브라우저 메뉴 허용 (붙여넣기 등)
            const tag = e.target.tagName;
            if (tag === 'INPUT' || tag === 'TEXTAREA') return;
            e.preventDefault();
        });
        
        // 키보드 단축키 (Ctrl+C, Ctrl+X, Ctrl+V)
        document.addEventListener('keydown', (e) => {
            // 입력 필드에서는 무시 (체크박스는 예외)
            if (e.target.tagName === 'TEXTAREA') return;
            if (e.target.tagName === 'INPUT' && e.target.type !== 'checkbox') return;
            if (!this.user) return;
            
            // 텍스트가 선택되어 있으면 브라우저 기본 복사/붙여넣기 허용
            const textSelection = window.getSelection();
            if (textSelection && textSelection.toString().trim().length > 0) return;
            
            // 모달이 열려있으면 파일 복사/붙여넣기 무시 (모달 내 텍스트 선택 가능하게)
            const hasVisibleModal = Array.from(document.querySelectorAll('.modal')).some(m => {
                const style = window.getComputedStyle(m);
                return style.display !== 'none' && style.visibility !== 'hidden';
            });
            if (hasVisibleModal) return;
            
            if (e.ctrlKey || e.metaKey) {
                // 체크박스 또는 클릭 선택된 항목 확인
                const hasSelection = this.getSelectedOrCheckedItems().length > 0;
                
                // e.code는 물리적 키 위치 기반이라 IME 상태와 무관
                const key = e.key?.toLowerCase();
                const code = e.code;
                const isC = key === 'c' || e.keyCode === 67 || code === 'KeyC';
                const isX = key === 'x' || e.keyCode === 88 || code === 'KeyX';
                const isV = key === 'v' || e.keyCode === 86 || code === 'KeyV';
                
                if (isC && hasSelection) {
                    e.preventDefault();
                    this.clipboardCopy();
                } else if (isX && hasSelection) {
                    e.preventDefault();
                    this.clipboardCut();
                } else if (isV && this.clipboard.items.length > 0) {
                    e.preventDefault();
                    this.clipboardPaste();
                }
            }
        });
        
