        // 백신 엔진 테스트 (저장 후 테스트)
        $('#btn-test-antivirus').on('click', async () => {
            const resultSpan = $('#antivirus-test-result');
            const engine = $('#antivirus-engine').val();
            
            if (engine === 'disabled') {
                resultSpan.text(t('select_scan_engine', '❌ 검사 엔진을 먼저 선택하세요')).css('color', '#f44336');
                return;
            }
            
            resultSpan.text(t('saving_settings', '설정 저장 중...')).css('color', '#666');
            
            // 먼저 현재 설정 저장
            const settings = {
                engine: engine,
                max_size: parseInt($('#antivirus-max-size').val() || '100'),
                clamav_path: $('#antivirus-clamav-path').val().trim(),
                defender_path: $('#antivirus-defender-path').val().trim(),
                block_on_error: $('#antivirus-block-on-error').is(':checked')
            };
            
            try {
                const saveRes = await this.api('antivirus_settings_save', settings);
                if (!saveRes.success) {
                    resultSpan.text('❌ ' + t('settings_save_failed', '설정 저장 실패') + ': ' + (saveRes.error || '')).css('color', '#f44336');
                    return;
                }
                
                resultSpan.text(t('testing', '테스트 중...')).css('color', '#666');
                
                const res = await this.api('antivirus_test', {}, 'GET');
                if (res.success) {
                    resultSpan.text('✅ ' + res.message).css('color', '#4caf50');
                } else {
                    resultSpan.text('❌ ' + (res.error || t('test_failed', '테스트 실패'))).css('color', '#f44336');
                }
            } catch (e) {
                resultSpan.text('❌ ' + t('error_prefix', '오류') + ': ' + e.message).css('color', '#f44336');
            }
        });
        
