        'html': 'html', 'htm': 'html',
        'css': 'css', 'scss': 'css', 'sass': 'css', 'less': 'css',
        'js': 'js', 'jsx': 'js', 'mjs': 'js', 'cjs': 'js',
        // 주의: ts는 동영상 (MPEG-TS), tsx만 JS 아이콘
        'tsx': 'js',
        'json': 'json', 'json5': 'json',
        'xml': 'xml', 'xsd': 'xml', 'xsl': 'xml',
        'php': 'php', 'phtml': 'php',
        'py': 'python', 'pyw': 'python',
        'java': 'java', 'class': 'java', 'jar': 'java',
