    // 비밀번호 입력 모달 (prompt 대체)
    async promptPassword(message) {
        return new Promise((resolve) => {
            const content = `
                <div style="margin-bottom: 12px; font-size: 14px;">${message}</div>
                <input type="password" id="prompt-password-input" class="form-control" style="width: 100%; padding: 10px 12px; font-size: 15px;" autocomplete="current-password">
            `;
            
            // 별도 오버레이 생성/가져오기
            let confirmOverlay = document.getElementById('confirm-modal-overlay');
            if (!confirmOverlay) {
                confirmOverlay = document.createElement('div');
                confirmOverlay.id = 'confirm-modal-overlay';
                confirmOverlay.style.cssText = `
                    position: fixed;
                    top: 0;
                    left: 0;
                    right: 0;
                    bottom: 0;
                    background: rgba(0,0,0,0.5);
                    display: flex;
                    align-items: center;
                    justify-content: center;
                    z-index: 10000;
                `;
                document.body.appendChild(confirmOverlay);
            }
            
            const confirmModal = document.getElementById('modal-confirm');
            confirmOverlay.appendChild(confirmModal);
            
            document.getElementById('confirm-modal-title').textContent = t('password_confirm', '비밀번호 확인');
            document.getElementById('confirm-modal-content').innerHTML = content;
            
            const footer = document.getElementById('confirm-modal-footer');
            footer.innerHTML = '';
            
            const hideModal = () => {
                confirmOverlay.style.display = 'none';
                confirmModal.style.display = 'none';
                const modalOverlay = document.getElementById('modal-overlay');
                if (modalOverlay && confirmModal.parentElement !== modalOverlay) {
                    modalOverlay.appendChild(confirmModal);
                }
            };
            
            const doConfirm = () => {
                const val = document.getElementById('prompt-password-input')?.value;
                document.removeEventListener('keydown', keyHandler);
                hideModal();
                resolve(val || null);
            };
            
            const doCancel = () => {
                document.removeEventListener('keydown', keyHandler);
                hideModal();
                resolve(null);
            };
            
            const keyHandler = (e) => {
                if (e.key === 'Enter') {
                    e.preventDefault();
                    e.stopImmediatePropagation();
                    doConfirm();
                } else if (e.key === 'Escape') {
                    e.preventDefault();
                    e.stopImmediatePropagation();
                    doCancel();
                }
            };
            
            const cancelBtn = document.createElement('button');
            cancelBtn.className = 'btn btn-secondary';
            cancelBtn.textContent = t('cancel');
            cancelBtn.onclick = doCancel;
            footer.appendChild(cancelBtn);
            
            const confirmBtn = document.createElement('button');
            confirmBtn.className = 'btn btn-primary';
            confirmBtn.textContent = t('confirm');
            confirmBtn.onclick = doConfirm;
            footer.appendChild(confirmBtn);
            
            document.addEventListener('keydown', keyHandler);
            
            // 모달 표시
            confirmOverlay.style.display = 'flex';
            confirmModal.style.display = 'flex';
            
            // 포커스
            setTimeout(() => {
                const input = document.getElementById('prompt-password-input');
                if (input) input.focus();
            }, 100);
        });
    },
    
